    60  otError Tlv::GetOffset(const Message &aMessage, uint8_t aType, uint16_t &aOffset)
    61  {
    62      otError  error  = OT_ERROR_NOT_FOUND;
    63      uint16_t offset = aMessage.GetOffset();
    64      uint16_t end    = aMessage.GetLength();
    65      Tlv      tlv;
    66
    67      while (offset + sizeof(tlv) <= end)
    68      {
    69          uint32_t length = sizeof(tlv);
    70
    71          aMessage.Read(offset, sizeof(tlv), &tlv);
    72
    73          if (tlv.GetLength() != kExtendedLength)
    74          {
    75              length += tlv.GetLength();
    76          }
    77          else
    78          {
    79              uint16_t extLength;
    80
    81              VerifyOrExit(sizeof(extLength) == aMessage.Read(offset + sizeof(tlv), sizeof(extLength), &extLength));
    82              length += sizeof(extLength) + HostSwap16(extLength);
    83          }
    84
    85          VerifyOrExit(offset + length <= end);
    86
    87          if (tlv.GetType() == aType)
    88          {
    89              aOffset = offset;
    90              ExitNow(error = OT_ERROR_NONE);
    91          }
    92
    93          offset += static_cast<uint16_t>(length);
    94      }
    95
    96  exit:
    97      return error;
    98  }
